        count = gf_list_count(moov->trackList);
        for (i = 0; i<count; i++) {
                GF_TrackBox *trak = (GF_TrackBox*)gf_list_get(moov->trackList, i);
                if ((trak->originalFile == originalFile) && (trak->originalID == originalID)) return trak;
        }
        return NULL;
}

